var ModalBienvenida = class extends Ob.Modal {
  constructor(plugin) {
    super(plugin.app);
    this.plugin = plugin;
  }
  onOpen() {
    this.modalEl.addClass("dvg-bienvenida");
    this.titleEl.setText("👋 Bienvenido a Visor + Gemini");
    let c = this.contentEl;
    let pasos = c.createDiv({ cls: "dvg-bv-pasos" });
    let paso = (emoji, titulo, texto) => {
      let p = pasos.createDiv({ cls: "dvg-bv-paso" });
      p.createDiv({ cls: "dvg-bv-emoji", text: emoji });
      let t = p.createDiv();
      t.createDiv({ cls: "dvg-bv-titulo", text: titulo });
      t.createDiv({ cls: "dvg-bv-texto", text: texto });
    };
    paso("📖", "Abre un libro", "Haz clic en cualquier PDF, EPUB o DjVu: se ve con todas las p\u00e1ginas seguidas.");
    paso("🧠", "Todo est\u00e1 en un bot\u00f3n", "El 🧠 de la barra de la izquierda abre un panel con Chat, Mapa mental, Prueba, Resumen y Voz.");
    paso("✅", "Elige p\u00e1ginas y genera", "En Mapa mental, Prueba o Resumen agregas p\u00e1ginas mientras lees y pulsas Generar.");
    paso("⏺", "Graba tus clases", "El ⏺ (tambi\u00e9n en el celular) graba al profesor y lo transcribe gratis y sin internet, con el audio de cada parte para corroborar.");
    paso("🟧", "Todo a un toque", "En el celular, el bot\u00f3n naranja al pie de la barra lateral (desliza desde el borde izquierdo) abre todas las funciones. El ? de cada una muestra c\u00f3mo se usa.");
    let acciones = c.createDiv({ cls: "dvg-bv-acciones" });
    let guia = acciones.createEl("button", { text: "Ver la gu\u00eda con un mapa de demostraci\u00f3n", cls: "mod-cta" });
    guia.onclick = () => {
      this.close();
      this.plugin.abrirGuia();
    };
    let libro = acciones.createEl("button", { text: "Empezar: elegir un libro" });
    libro.onclick = () => {
      this.close();
      this.plugin.elegirLibroYSeleccionar("mapa");
    };
  }
  async onClose() {
    this.contentEl.empty();
    this.plugin.settings.guiaMostrada = true;
    await this.plugin.saveSettings();
  }
};

