/**
 * Botón del MODO VOZ: micrófono con ondas (no el logo de Gemini), para que se
 * entienda de un vistazo que es "hablar con Gemini". Las ondas se mueven
 * mientras la sesión de voz está activa.
 */
// ===========================================================================
// GRABAR CLASE (pensado para el celular)
// ---------------------------------------------------------------------------
// Graba al profesor con el ruido de fondo reducido, en audio liviano (Opus), y
// lo parte en fragmentos de ~1 minuto que se cortan en las pausas (nunca a mitad
// de palabra). Cada fragmento se guarda al tiro como archivo y se transcribe
// con Gemini. La nota de la clase queda así:
//
//   ## 12:30 · Flujo a través de una esfera
//   Lo que dijo el profesor en ese minuto…
//   ![[…/012.webm]]            ← el audio exacto de ese texto
//
// Así se busca una frase (buscador de Obsidian, o el chat del 🧠) y se escucha
// justo dónde se dijo. Sin internet, la transcripción queda en cola y se hace
// sola después (la cola sobrevive a cerrar Obsidian).
// ===========================================================================
var TIPO_GRABACION = "dvg-grabacion";
var CALIDADES_GRABACION = {
  liviana: { kbps: 16, etiqueta: "Liviana (~7 MB por hora)" },
  normal: { kbps: 24, etiqueta: "Normal (~11 MB por hora)" },
  alta: { kbps: 32, etiqueta: "Alta (~14 MB por hora)" },
};
// min: desde aquí se corta en la primera pausa clara; max: desde aquí en cualquier pausa; tope: se corta sí o sí
var LARGOS_FRAGMENTO = {
  corto: { min: 15, max: 30, tope: 45, etiqueta: "Cortos (15 a 30 s)" },
  normal: { min: 30, max: 60, tope: 90, etiqueta: "Normales (30 s a 1 min)" },
  largo: { min: 60, max: 120, tope: 150, etiqueta: "Largos (1 a 2 min)" },
};
var DIAS_ES = ["domingo", "lunes", "martes", "miércoles", "jueves", "viernes", "sábado"];
var MESES_ES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];

function relojClase(seg) {
  seg = Math.max(0, Math.floor(seg || 0));
  let h = Math.floor(seg / 3600);
  let m = Math.floor((seg % 3600) / 60);
  let s = seg % 60;
  let dos = (n) => String(n).padStart(2, "0");
  return h ? h + ":" + dos(m) + ":" + dos(s) : dos(m) + ":" + dos(s);
}

function segundosDeReloj(t) {
  return String(t || "")
    .split(":")
    .map((x) => parseInt(x, 10) || 0)
    .reduce((a, b) => a * 60 + b, 0);
}

function tres(n) {
  return String(n).padStart(3, "0");
}

function fechaLargaEs(d) {
  let dos = (n) => String(n).padStart(2, "0");
  return DIAS_ES[d.getDay()] + " " + d.getDate() + " de " + MESES_ES[d.getMonth()] + " de " + d.getFullYear() + ", " + dos(d.getHours()) + ":" + dos(d.getMinutes());
}

function tamanoLegible(bytes) {
  if (!bytes) return "0 KB";
  return bytes < 1048576 ? Math.max(1, Math.round(bytes / 1024)) + " KB" : (bytes / 1048576).toFixed(1).replace(".", ",") + " MB";
}

function base64DeBytes(buffer) {
  let b = new Uint8Array(buffer);
  let partes = [];
  for (let i = 0; i < b.length; i += 0x8000) partes.push(String.fromCharCode.apply(null, b.subarray(i, i + 0x8000)));
  return btoa(partes.join(""));
}

/** El formato más liviano que este dispositivo sabe grabar (Opus; en iPhone antiguos, AAC). */
function formatoGrabacion() {
  if (typeof MediaRecorder === "undefined") return null;
  let opciones = [
    ["audio/webm;codecs=opus", "webm"],
    ["audio/ogg;codecs=opus", "ogg"],
    ["audio/mp4;codecs=mp4a.40.2", "m4a"],
    ["audio/mp4", "m4a"],
    ["audio/webm", "webm"],
  ];
  for (let [mime, ext] of opciones) {
    try {
      if (MediaRecorder.isTypeSupported(mime)) return { mime, ext };
    } catch (e) {}
  }
  return { mime: "", ext: "webm" };
}

function extensionDeTipo(tipo) {
  return /mp4|m4a|aac/i.test(tipo) ? "m4a" : /ogg/i.test(tipo) ? "ogg" : "webm";
}

function mimeDeExtension(ext) {
  return ext === "m4a" ? "audio/mp4" : ext === "ogg" ? "audio/ogg" : ext === "mp3" ? "audio/mpeg" : ext === "wav" ? "audio/wav" : "audio/webm";
}

function vintDeLargo(valor, largo) {
  if (valor >= Math.pow(2, 7 * largo) - 1) return null;
  let r = new Uint8Array(largo);
  for (let k = largo - 1; k >= 0; k--) {
    r[k] = valor % 256;
    valor = Math.floor(valor / 256);
  }
  r[0] |= 0x80 >> (largo - 1);
  return r;
}

/**
 * MediaRecorder escribe WebM sin duración: el reproductor no muestra el largo ni
 * deja adelantar. Se agrega Duration (dentro de Info) con lo que duró de verdad.
 * Devuelve un ArrayBuffer nuevo, o null si el archivo no tiene la forma esperada.
 */
function fijarDuracionWebm(buffer, segundos) {
  try {
    let b = new Uint8Array(buffer);
    let leerId = (i) => {
      let l = 1;
      let m = 0x80;
      while (l <= 4 && !(b[i] & m)) {
        l++;
        m >>= 1;
      }
      if (l > 4 || i + l > b.length) return null;
      let v = 0;
      for (let k = 0; k < l; k++) v = v * 256 + b[i + k];
      return { v, l };
    };
    let leerTam = (i) => {
      let l = 1;
      let m = 0x80;
      while (l <= 8 && !(b[i] & m)) {
        l++;
        m >>= 1;
      }
      if (l > 8 || i + l > b.length) return null;
      let v = b[i] & (m - 1);
      let unos = v === m - 1;
      for (let k = 1; k < l; k++) {
        v = v * 256 + b[i + k];
        if (b[i + k] !== 0xff) unos = false;
      }
      return { v, l, desconocido: unos };
    };
    let e = leerId(0);
    if (!e || e.v !== 0x1a45dfa3) return null;
    let t = leerTam(e.l);
    let i = e.l + t.l + t.v;
    e = leerId(i);
    if (!e || e.v !== 0x18538067) return null;
    let posTamSeg = i + e.l;
    let tamSeg = leerTam(posTamSeg);
    let dentro = posTamSeg + tamSeg.l;
    let fin = tamSeg.desconocido ? b.length : Math.min(b.length, dentro + tamSeg.v);
    for (let j = dentro; j < fin; ) {
      let ei = leerId(j);
      if (!ei) return null;
      let ti = leerTam(j + ei.l);
      if (!ti) return null;
      let datos = j + ei.l + ti.l;
      // Clusters sin haber visto Info, o un índice (SeekHead) que habría que corregir: no se toca
      if (ei.v === 0x1f43b675 || ei.v === 0x114d9b74) return null;
      if (ei.v === 0x1549a966) {
        let finInfo = datos + ti.v;
        let escala = 1000000;
        let posDur = -1;
        let largoDur = 0;
        for (let k = datos; k < finInfo; ) {
          let ek = leerId(k);
          let tk = ek && leerTam(k + ek.l);
          if (!ek || !tk) return null;
          let dk = k + ek.l + tk.l;
          if (ek.v === 0x2ad7b1) {
            let v = 0;
            for (let q = 0; q < tk.v; q++) v = v * 256 + b[dk + q];
            escala = v || escala;
          }
          if (ek.v === 0x4489) {
            posDur = dk;
            largoDur = tk.v;
          }
          k = dk + tk.v;
        }
        let valor = (segundos * 1e9) / escala;
        if (posDur >= 0) {
          let copia = b.slice();
          let vista = new DataView(copia.buffer);
          if (largoDur === 8) vista.setFloat64(posDur, valor);
          else if (largoDur === 4) vista.setFloat32(posDur, valor);
          else return null;
          return copia.buffer;
        }
        let dur = new Uint8Array(11);
        dur[0] = 0x44;
        dur[1] = 0x89;
        dur[2] = 0x88;
        new DataView(dur.buffer).setFloat64(3, valor);
        let tamInfo = vintDeLargo(ti.v + 11, ti.l) || vintDeLargo(ti.v + 11, 8);
        let delta = 11 + tamInfo.length - ti.l;
        let salida = new Uint8Array(b.length + delta);
        let p = 0;
        for (let x of [b.subarray(0, j + ei.l), tamInfo, b.subarray(datos, finInfo), dur, b.subarray(finInfo)]) {
          salida.set(x, p);
          p += x.length;
        }
        if (!tamSeg.desconocido) {
          let nuevo = vintDeLargo(tamSeg.v + delta, tamSeg.l);
          if (!nuevo) return null;
          salida.set(nuevo, posTamSeg);
        }
        return salida.buffer;
      }
      if (ti.desconocido) return null;
      j = datos + ti.v;
    }
  } catch (e) {}
  return null;
}

async function abrirMicrofonoClase(settings) {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) throw new Error("Este dispositivo no deja usar el micrófono desde Obsidian.");
  let limpiar = settings.grabarReducirRuido !== false;
  let r = {
    channelCount: 1,
    noiseSuppression: limpiar,
    autoGainControl: limpiar,
    // En iPhone la reducción de ruido viene junto con el "procesado de voz" (que es el eco)
    echoCancellation: limpiar && !!(Ob.Platform && Ob.Platform.isIosApp),
  };
  if (settings.preferredMicDeviceId) r.deviceId = { exact: settings.preferredMicDeviceId };
  try {
    return await navigator.mediaDevices.getUserMedia({ audio: r });
  } catch (e) {
    if (r.deviceId && e && (e.name === "OverconstrainedError" || e.name === "NotFoundError")) {
      delete r.deviceId;
      return await navigator.mediaDevices.getUserMedia({ audio: r });
    }
    throw e;
  }
}

function mensajeMicrofono(e) {
  let n = (e && e.name) || "";
  if (n === "NotAllowedError" || n === "SecurityError")
    return "Obsidian no tiene permiso para usar el micrófono. Actívalo en los ajustes del teléfono (Aplicaciones → Obsidian → Permisos → Micrófono) y vuelve a intentar.";
  if (n === "NotFoundError") return "No encontré un micrófono en este dispositivo.";
  if (n === "NotReadableError") return "Otra aplicación está usando el micrófono. Ciérrala y vuelve a intentar.";
  return "No pude empezar a grabar: " + ((e && e.message) || e);
}

