  // =========================================================================
  // EL RECORRIDO (la demo en pantalla)
  // Es un modal de Obsidian: el botón Atrás del celular y Esc lo cierran.
  // =========================================================================
  function buscar(raiz, paso) {
    if (!raiz || !paso) return null;
    let lista = [];
    try {
      if (paso.sel) lista = Array.from(raiz.querySelectorAll(paso.sel));
      else if (paso.boton) {
        let pref = [].concat(paso.boton).map(sinTildes);
        lista = Array.from(raiz.querySelectorAll("button")).filter((b) => {
          let t = sinTildes(b.textContent);
          return pref.some((x) => t.startsWith(x));
        });
      }
    } catch (e) {
      return null;
    }
    return lista.find(visible) || null;
  }

  function pasosDe(demo, raiz) {
    return demo.pasos.filter((p) => {
      if (!raiz) return !p.vacio; // contada: todo menos lo que es para una sección vacía
      if (!p.solo || p.sin) return true;
      return !!buscar(raiz, p);
    });
  }

  /** Lo que ocupan la barra de estado y el borde de abajo del teléfono (en px). */
  var _margenes = null;
  function margenesSeguros() {
    if (_margenes) return _margenes;
    let sonda = document.body.createDiv();
    // Obsidian (celular) deja los márgenes en --safe-area-inset-*; si no están, los del navegador
    sonda.style.cssText =
      "position:fixed;visibility:hidden;pointer-events:none;top:0;left:0;" +
      "padding-top:var(--safe-area-inset-top, env(safe-area-inset-top, 0px));padding-bottom:var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px));";
    let cs = window.getComputedStyle(sonda);
    _margenes = { arriba: parseFloat(cs.paddingTop) || 0, abajo: parseFloat(cs.paddingBottom) || 0 };
    sonda.remove();
    return _margenes;
  }

  var _demoAbierta = null;
  var ModalDemo = class extends Ob.Modal {
    constructor(app, demo, raiz, op) {
      super(app);
      this.demo = demo;
      this.raiz = raiz || null;
      this.op = op || {};
      this.pasos = pasosDe(demo, this.raiz);
      if (!this.pasos.length) this.pasos = [{ titulo: demo.titulo, texto: "Esta parte no está en pantalla ahora." }];
      this.i = 0;
      this.el = null;
    }
    onOpen() {
      if (_demoAbierta && _demoAbierta !== this) _demoAbierta.close();
      _demoAbierta = this;
      let cont = this.containerEl;
      cont.addClass("dvc-demo-cont");
      this.modalEl.addClass("dvc-demo-tarjeta");
      this.modalEl.setAttribute("role", "dialog");
      this.modalEl.setAttribute("aria-label", "Demo: " + this.demo.titulo);
      // El mapa mental en pantalla completa tapa todo lo demás: la demo va adentro
      let fs = document.fullscreenElement;
      if (fs && !fs.contains(cont)) fs.appendChild(cont);
      this.veloEl = createDiv({ cls: "dvc-demo-velo" });
      this.focoEl = createDiv({ cls: "dvc-demo-foco is-oculto" });
      cont.insertBefore(this.focoEl, this.modalEl);
      cont.insertBefore(this.veloEl, this.focoEl);
      try {
        this.scope.register([], "ArrowRight", () => (this.ir(1), false));
        this.scope.register([], "ArrowLeft", () => (this.ir(-1), false));
      } catch (e) {}
      this._mover = () => this.programar();
      window.addEventListener("resize", this._mover);
      document.addEventListener("scroll", this._mover, true);
      // Lo de abajo puede moverse solo (un modal que se anima, algo que termina de cargar)
      this._reloj = window.setInterval(() => this.posicionar(), 300);
      this.mostrar(0);
    }
    onClose() {
      window.clearInterval(this._reloj);
      window.cancelAnimationFrame(this._cuadro);
      window.removeEventListener("resize", this._mover);
      document.removeEventListener("scroll", this._mover, true);
      if (_demoAbierta === this) _demoAbierta = null;
      this.contentEl.empty();
    }
    programar() {
      window.cancelAnimationFrame(this._cuadro);
      this._cuadro = window.requestAnimationFrame(() => this.posicionar());
    }
    ir(d) {
      let i = this.i + d;
      if (i < 0 || i >= this.pasos.length) return;
      this.mostrar(i);
    }
    mostrar(i) {
      this.i = i;
      let paso = this.pasos[i];
      this.el = this.raiz ? buscar(this.raiz, paso) : null;
      if (this.el) {
        try {
          this.el.scrollIntoView({ block: "center", inline: "center", behavior: "smooth" });
        } catch (e) {
          try {
            this.el.scrollIntoView();
          } catch (e2) {}
        }
      }
      this.pintarTarjeta(paso);
      this.posicionar();
      window.setTimeout(() => this.posicionar(), 420);
    }
    pintarTarjeta(paso) {
      let c = this.contentEl;
      c.empty();
      let total = this.pasos.length;
      let cab = c.createDiv({ cls: "dvc-demo-cab" });
      cab.createSpan({ cls: "dvc-demo-chip", text: "Demo" });
      cab.createSpan({ cls: "dvc-demo-donde", text: this.demo.titulo });
      let cerrar = cab.createEl("button", { cls: "dvc-demo-cerrar", attr: { type: "button", "aria-label": "Salir de la demo" } });
      icono(cerrar, "x");
      cerrar.onclick = () => this.close();
      c.createDiv({ cls: "dvc-demo-titulo", text: paso.titulo });
      c.createDiv({ cls: "dvc-demo-texto", text: (!this.el && paso.sin) || paso.texto });
      if (this.op.aviso && this.i === 0) c.createDiv({ cls: "dvc-demo-aviso", text: this.op.aviso });
      let pie = c.createDiv({ cls: "dvc-demo-pie" });
      let izq = pie.createDiv({ cls: "dvc-demo-avance" });
      if (total > 1) {
        let puntos = izq.createDiv({ cls: "dvc-demo-puntos", attr: { "aria-hidden": "true" } });
        for (let k = 0; k < total; k++) puntos.createSpan({ cls: "dvc-demo-punto" + (k === this.i ? " is-actual" : k < this.i ? " is-visto" : "") });
        izq.createSpan({ cls: "dvc-demo-cuenta", text: this.i + 1 + " de " + total });
      }
      let botones = pie.createDiv({ cls: "dvc-demo-botones" });
      if (this.i > 0) {
        let a = botones.createEl("button", { cls: "dvc-demo-btn", text: "Anterior", attr: { type: "button" } });
        a.onclick = () => this.ir(-1);
      }
      let ultimo = this.i === total - 1;
      let final = ultimo && this.op.final ? this.op.final : null;
      let sig = botones.createEl("button", { cls: "dvc-demo-btn mod-cta", text: ultimo ? (final ? final.rotulo : "Listo") : "Siguiente", attr: { type: "button" } });
      sig.onclick = () => {
        if (!ultimo) return this.ir(1);
        this.close();
        if (final) Promise.resolve().then(final.accion).catch((e) => new Ob.Notice(mensajeDe(e), 8000));
      };
      window.setTimeout(() => {
        try {
          sig.focus({ preventScroll: true });
        } catch (e) {}
      }, 30);
    }
    posicionar() {
      let tarjeta = this.modalEl;
      if (!tarjeta || !tarjeta.isConnected) return;
      let vw = window.innerWidth;
      let vh = window.innerHeight;
      let seg = margenesSeguros();
      let el = this.el && visible(this.el) ? this.el : null;
      let r = null;
      if (el) {
        let b = el.getBoundingClientRect();
        let m = 6;
        let x1 = Math.max(4, b.left - m);
        let y1 = Math.max(4 + seg.arriba, b.top - m);
        let x2 = Math.min(vw - 4, b.right + m);
        let y2 = Math.min(vh - 4 - seg.abajo, b.bottom + m);
        if (x2 - x1 >= 10 && y2 - y1 >= 10) r = { left: x1, top: y1, right: x2, bottom: y2, width: x2 - x1, height: y2 - y1 };
      }
      let foco = this.focoEl;
      if (r) {
        foco.style.left = r.left + "px";
        foco.style.top = r.top + "px";
        foco.style.width = r.width + "px";
        foco.style.height = r.height + "px";
        foco.removeClass("is-oculto");
        this.veloEl.addClass("is-oculto");
      } else {
        foco.addClass("is-oculto");
        this.veloEl.removeClass("is-oculto");
      }
      // La tarjeta: en el teléfono va de borde a borde, arriba o abajo según dónde esté lo resaltado
      let telefono = vw < 600;
      let ancho = telefono ? vw - 24 : Math.min(400, vw - 32);
      // Por variables: el CSS las aplica con !important, así ningún estilo de modal del tema las pisa
      tarjeta.style.setProperty("--dvc-ancho", ancho + "px");
      let alto = tarjeta.offsetHeight || 180;
      let arriba = 12 + seg.arriba;
      let abajo = vh - alto - 12 - seg.abajo;
      let left;
      let top;
      if (!r) {
        left = (vw - ancho) / 2;
        top = telefono ? abajo : Math.max(arriba, (vh - alto) / 2);
      } else if (telefono) {
        left = 12;
        let centro = (r.top + r.bottom) / 2;
        top = centro > vh * 0.52 ? arriba : abajo;
      } else {
        left = Math.min(Math.max(16, r.left + r.width / 2 - ancho / 2), vw - ancho - 16);
        if (vh - r.bottom >= alto + 28) top = r.bottom + 14;
        else if (r.top >= alto + 28) top = r.top - alto - 14;
        else top = abajo;
      }
      tarjeta.style.setProperty("--dvc-x", Math.round(left) + "px");
      tarjeta.style.setProperty("--dvc-y", Math.round(Math.max(arriba, Math.min(top, abajo))) + "px");
    }
  };

  /**
   * Empieza la demo `clave`. `raiz`: el elemento de la función abierta (null = demo contada,
   * sin resaltar). op: { aviso, final: { rotulo, accion } }.
   */
  function demo(clave, raiz, op) {
    let d = DEMOS[clave];
    if (!d) {
      new Ob.Notice("Esta parte todavía no tiene demo.");
      return null;
    }
    let app = (PLUGIN_VISOR && PLUGIN_VISOR.app) || window.app;
    let m = new ModalDemo(app, d, raiz, op);
    m.open();
    return m;
  }

  /** El botón «?». clave y raiz pueden ser funciones (se leen al tocarlo). */
  function ayuda(padre, clave, raiz, op) {
    op = op || {};
    let b = padre.createEl("button", { cls: "dvc-ayuda" + (op.cls ? " " + op.cls : ""), attr: { type: "button" } });
    b.setText("?");
    let k0 = clave;
    if (typeof clave === "function") {
      try {
        k0 = clave();
      } catch (e) {
        k0 = null;
      }
    }
    let titulo = op.etiqueta || (k0 && DEMOS[k0] ? DEMOS[k0].titulo : "");
    b.setAttribute("aria-label", "Demo: cómo se usa" + (titulo ? " «" + titulo + "»" : " esta parte"));
    b.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      if (op.alClic) return void op.alClic(ev);
      let k = typeof clave === "function" ? clave() : clave;
      let r = typeof raiz === "function" ? raiz() : raiz;
      demo(k, r || null);
    });
    return b;
  }

  /** «?» al lado de un título (sin meterse en la línea de color que lo subraya). */
  function ayudaTitulo(h, clave, raiz) {
    if (!h) return null;
    h.addClass("dvc-con-ayuda");
    return ayuda(h, clave, raiz, { cls: "dvc-ayuda-titulo" });
  }

  function aplicarAyudas(plugin) {
    document.body.toggleClass("dvc-sin-ayudas", plugin.settings.centroAyudas === false);
  }

