  function vistaDoc(plugin) {
    try {
      return (plugin.vistaParaHub && plugin.vistaParaHub()) || null;
    } catch (e) {
      return null;
    }
  }
  function hayDocumento(plugin) {
    if (vistaDoc(plugin)) return true;
    try {
      let h = plugin.app.workspace.getLeavesOfType(TIPO_CHAT_LIBRO)[0];
      return !!(h && h.view && h.view.ruta);
    } catch (e) {
      return false;
    }
  }
  /** Corre un comando del plugin. false si no se pudo (por ejemplo, falta la nota abierta). */
  function comando(plugin, id) {
    let c = plugin.app.commands;
    try {
      return !!(c && c.executeCommandById && c.executeCommandById(plugin.manifest.id + ":" + id));
    } catch (e) {
      return false;
    }
  }
  function abrirAjustes(plugin) {
    let s = plugin.app.setting;
    if (!s || !s.open) return void new Ob.Notice("Abre Ajustes de Obsidian y busca «Visor + Gemini».");
    s.open();
    if (s.openTabById) s.openTabById(plugin.manifest.id);
  }
  function generar(plugin, modo) {
    let v = vistaDoc(plugin);
    if (v) return plugin.abrirSeleccion(v, modo);
    return plugin.elegirLibroYSeleccionar(modo);
  }
  async function hablarConLibro(plugin) {
    let v = vistaDoc(plugin);
    if (!v) return plugin.abrirHub();
    let hub = await plugin.abrirChat(v);
    if (hub && hub.alternarVoz) return hub.alternarVoz();
    return plugin.alternarAsistente(v);
  }

