    // --- Archivos ---
    add({ id: "buscar", grupo: "archivos", titulo: "Buscar archivos", desc: "Ordenados por carpeta y subcarpeta", icono: "folder-search", claves: "encontrar archivo nota carpeta explorador abrir", demo: "buscar", raiz: ".modal.dvs-modal", accion: () => BUSCAR.abrir(plugin) });
    let escritorio = !!Ob.Platform.isDesktopApp;
